### Steps
1, Show the bottom sheet first
2, Tap the back arrow and the `show bottom sheet` button at the same time
3, Repeat step 2 many times and observe the log output, which can be reproduced with a high probability

### Code
```dart
import 'package:flutter/material.dart';

void main() {
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Flutter Demo',
      home: Scaffold(
        appBar: AppBar(
          title: const Text('Flutter Demo'),
        ),
        body: const MyHomePage(),
      ),
      // home : SizedBox.shrink(),
    );
  }
}

class MyHomePage extends StatefulWidget {
  const MyHomePage({Key? key}) : super(key: key);

  @override
  State<MyHomePage> createState() => _MyHomePageState();
}

class _MyHomePageState extends State<MyHomePage> {
  void bottomSheet() {
    Scaffold.of(context).showBottomSheet((BuildContext context) {
      return const FractionallySizedBox(
        heightFactor: .2,
        child: Center(child: Text('This is a bottom sheet')),
      );
    }, backgroundColor: Colors.amber);
  }

  @override
  Widget build(BuildContext context) {
    return ElevatedButton(
      child: const Text('Show bottom sheet'),
      onPressed: bottomSheet,
    );
  }
}

```

